package com.fixmer.mared.technology.server.setup;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;import com.google.gson.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;import java.nio.file.*;import java.util.*;import java.util.function.Consumer;
/** Explicit generation choice. An older world is never substituted for a missing latest checkpoint. */
public final class RecoveryScreen77 extends MaredScreen {
 private final Screen previous;private final Consumer<String> chosen;private final RecoveryService77 service=new RecoveryService77();private String rootValue,scanned="";private EditBox root;private Button scan,recover,prev,next,back,browse,reports;private int selected,left,w,scroll,maxScroll;private boolean delivered;
 public RecoveryScreen77(Screen previous,String root,Consumer<String> chosen){super(tr("title"));this.previous=previous;this.rootValue=root;this.chosen=chosen;}
 private static Component tr(String key,Object...args){return Component.translatable("mared.recovery77."+key,args);}
 private Button button(Component title,int x,int y,int width,Runnable action){return addRenderableWidget(Button.builder(title,b->action.run()).bounds(x,y,width,20).build());}
 @Override protected void init(){w=Math.max(250,Math.min(650,width-24));left=(width-w)/2;root=addRenderableWidget(new EditBox(font,left,40,w-34,20,tr("root")));root.setMaxLength(4096);root.setValue(rootValue);browse=button(Component.literal("…"),left+w-30,40,30,()->{rootValue=root.getValue();Path path;try{path=Path.of(rootValue);}catch(Exception bad){path=minecraft.gameDirectory.toPath();}minecraft.setScreen(new LocalPickerScreen68(this,true,path,p->{rootValue=p.toString();root.setValue(rootValue);}));});int bw=(w-8)/3;scan=button(tr("scan"),left,64,bw,()->{rootValue=root.getValue().trim();scanned=rootValue;selected=scroll=0;service.scan(scanned);});prev=button(tr("previous"),left+bw+4,64,bw,()->{selected++;scroll=0;});next=button(tr("next"),left+2*(bw+4),64,bw,()->{selected--;scroll=0;});recover=button(tr("recover"),left,height-50,w,this::confirm);back=button(tr("back"),left,height-26,(w-4)/2,this::onClose);reports=button(tr("reports"),left+(w+4)/2,height-26,(w-4)/2,()->{try{String path=reportPath();net.minecraft.Util.getPlatform().openFile(Path.of(path).toFile());}catch(Exception ignored){}});tick();}
 private String reportPath(){if(!service.created().isEmpty())return service.created();JsonObject d=service.data();for(String k:List.of("incompleteRoot","successor"))if(d.has(k)&&!d.get(k).getAsString().isEmpty())return d.get(k).getAsString();return "";}
 private JsonArray rows(){try{return service.data().getAsJsonArray("rows");}catch(Exception bad){return null;}}
 private JsonObject row(){JsonArray rows=rows();if(rows==null||rows.size()==0)return null;selected=Math.max(0,Math.min(selected,rows.size()-1));return rows.get(selected).getAsJsonObject();}
 private boolean repairPending(){JsonObject d=service.data();return d.has("repairPending")&&d.get("repairPending").getAsBoolean();}
 private void confirm(){if(repairPending()&&root.getValue().trim().equals(scanned)){rootValue=root.getValue();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)service.repair(scanned);},tr("confirm_title"),Component.translatable("mared.https78.repair_confirm")));return;}JsonObject row=row();if(row==null||!row.get("eligible").getAsBoolean()||!root.getValue().trim().equals(scanned))return;JsonObject snapshot=row.deepCopy();boolean older=!snapshot.get("latest").getAsBoolean();rootValue=root.getValue();minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)service.recover(scanned,snapshot,older);},tr("confirm_title"),tr(older?"confirm_older":snapshot.get("kind").getAsString().equals("LEGACY76")?"confirm_legacy":"confirm",snapshot.get("generation").getAsString())));}
 @Override public void tick(){if(root==null)return;JsonObject r=row();boolean idle=!service.busy()&&service.created().isEmpty();root.setEditable(idle);scan.active=browse.active=idle;prev.active=idle&&rows()!=null&&selected+1<rows().size();next.active=idle&&selected>0;back.active=!service.busy();reports.active=!service.busy()&&!reportPath().isEmpty();recover.setMessage(repairPending()?Component.translatable("mared.https78.repair"):tr("recover"));recover.active=idle&&(repairPending()||r!=null&&r.get("eligible").getAsBoolean())&&root.getValue().trim().equals(scanned);}
 @Override public void removed(){if(root!=null)rootValue=root.getValue();}
 @Override public void onClose(){if(service.busy())return;if(!delivered&&!service.created().isEmpty()){delivered=true;chosen.accept(service.created());}minecraft.setScreen(previous);}
 @Override public boolean isPauseScreen(){return false;}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*24)));return true;}
 private List<Component> lines(){List<Component> out=new ArrayList<>();String result=service.result();boolean known=Set.of("IDLE","WORKING","SCANNED","CREATED","PUBLICATION79_PUBLISHER_BUSY","DEDICATED77_OWNER_ACTIVE","DEDICATED74_SOURCE_WORLD_BUSY","DEDICATED77_SELECTION_CHANGED","DEDICATED77_PROFILE_CHANGED","DEDICATED77_PAIR_CHANGED","DEDICATED77_RELEASE_INVENTORY","DEDICATED77_INCOMPLETE_RECOVERY","DEDICATED77_OPERATION_TIMEOUT","DEDICATED77_WINDOWS_ONLY","DEDICATED77_REFUSED","DEDICATED77_OLDER_WORLD_REQUIRES_CHOICE","DEDICATED77_ALREADY_RECOVERED","DEDICATED74_CORE_REJECTED").contains(result);out.add(tr("result."+(known?result:"DEDICATED77_REFUSED")));if(!known)out.add(Component.literal(result));out.add(tr("hint"));if(!root.getValue().trim().equals(scanned)&&!scanned.isEmpty())out.add(tr("rescan"));JsonObject r=row();if(r!=null){out.add(tr("generation",r.get("generation").getAsString()));out.add(tr(r.get("latest").getAsBoolean()?"latest":"older"));String reason=r.get("reason").getAsString();boolean reasonKnown=Set.of("CLEAN_CHECKPOINT","LEGACY_STOPPED_IMPORT","DEDICATED77_NO_CLEAN_CHECKPOINT","DEDICATED77_ALREADY_RECOVERED","DEDICATED77_RECEIPT","DEDICATED77_RECEIPT_CHANGED","DEDICATED77_CHECKPOINT_BINDING","DEDICATED77_INVENTORY_CHANGED","DEDICATED77_SESSION").contains(reason);out.add(tr("reason."+(reasonKnown?reason:"generic")));if(!reasonKnown)out.add(Component.literal(reason));if(!r.get("savedAt").getAsString().isEmpty())try{out.add(tr("saved",java.time.Instant.ofEpochMilli(Long.parseLong(r.get("savedAt").getAsString())).toString()));}catch(Exception ignored){}out.add(tr("release",r.get("release").getAsString()));}if(service.data().has("successor")&&!service.data().get("successor").getAsString().isEmpty()){out.add(tr("successor"));out.add(Component.literal(service.data().get("successor").getAsString()));}if(service.data().has("incompleteRoot")){out.add(tr("incomplete"));out.add(Component.literal(service.data().get("incompleteRoot").getAsString()));}if(!service.created().isEmpty()){out.add(tr("created"));out.add(Component.literal(service.created()));out.add(tr("start_hint"));}return out;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,10,0xFFFFFFFF);g.drawString(font,tr("root"),left,28,0xFFCCD0DC,false);List<net.minecraft.util.FormattedCharSequence> rows=new ArrayList<>();for(Component c:lines())rows.addAll(font.split(c,w-8));int top=90,bottom=Math.max(top,height-56),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var line:rows){if(y+step>=top&&y<bottom)g.drawString(font,line,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);}
}
